		}
		respond(w, http.StatusOK, "", map[string]string{"status": "ok", "product": product})
	})
	mux.HandleFunc("/api/tickets", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			tickets := store.list()
			if tickets == nil {
